def transform(grid):
    out=[row[:] for row in grid]
    # Read nonzero key colors row-major, then paint the occupied 4x4 blocks
    # of the 8-shape in reverse order.
    key=[grid[r][c] for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] not in (0,8)]
    blocks=[]
    for r0 in range(3,15,4):
        for c0 in range(2,14,4):
            if any(grid[r][c]==8 for r in range(r0,min(r0+4,len(grid))) for c in range(c0,min(c0+4,len(grid[0])))):
                blocks.append((r0,c0))
    # the figure has block positions listed in reading order; colors are reversed key order
    for (r0,c0),color in zip(blocks,reversed(key)):
        for r in range(r0,min(r0+4,len(grid))):
            for c in range(c0,min(c0+4,len(grid[0]))):
                if grid[r][c]==8: out[r][c]=color
    return out
